// Shared helper for defs that build themselves out of other defs. The type-only
// registry import keeps this out of the import cycle (registry imports every
// defs file, and every defs file imports this).

import type { Prim } from "@/lib/sketch/kit"
import { place } from "@/lib/sketch/kit"
import type { ComponentDef, Props } from "./registry"

/** Compose a child def at an offset. */
export function sub(def: ComponentDef, props: Props, x: number, y: number, w: number, h: number): Prim[] {
  return place(def.render({ ...def.defaults, ...props }, w, h), x, y)
}

"use client"

// ---------------------------------------------------------------------------
// window.squig — the canvas, from the other side of the glass.
//
// This is how an agent driving a real browser works the drawing: Playwright,
// Claude in Chrome, or a person with the devtools console open. Every call
// here goes through the store, which is the whole point — the human watching
// sees it land, ⌘Z takes it back, and it autosaves like their own edits. An
// agent that reached into the node map directly would get all three wrong.
//
// The rules about what a node may be live in lib/doc, not here: this file
// builds the node, hands it to lib/doc to be vouched for, and passes the
// vouched result on to the store. So the message you get for a taken id is
// the same sentence the CLI and the MCP server print. Glue, not logic.
// ---------------------------------------------------------------------------

import {
  addNodes,
  arrowNode,
  componentNode,
  describeComponent,
  docBounds,
  listComponents,
  nodesOf,
  shapeNode,
  textNode,
  updateNode,
  type ArrowOpts,
  type ComponentAt,
  type ComponentInfo,
  type ComponentSummary,
  type ShapeAt,
  type SquigDocument,
  type TextAt,
} from "./doc"
import { resizeSpacedNodes, spaceNodes, tidyNodes, type SpacingOptions, type SpacingAxis } from "./canvas/spacing"
import { renderSvg } from "./sketch/svg"
import { lookOf, useSquig } from "./store"
import type { Box, ShapeKind, SquigNode } from "./types"

export interface SquigAgentApi {
  version: 1
  /** Identify the open canvas before editing an existing browser tab. */
  documentId(): string
  /** the open document as a value — a copy, not the store's objects */
  doc(): SquigDocument
  serialize(): string
  /** replace the canvas with a .squig.json; false when it isn't one */
  load(json: string): boolean
  /** put finished nodes on top of the drawing and select them; returns their ids */
  add(nodes: SquigNode[]): string[]
  addComponent(kind: string, at: ComponentAt): string
  addText(text: string, at: TextAt): string
  addShape(shape: ShapeKind, at: ShapeAt): string
  addArrow(opts: ArrowOpts): string
  update(id: string, patch: Partial<SquigNode>): void
  remove(ids: string[]): void
  /** ⌘G on these; the new group's id, or null when there was nothing to group */
  group(ids: string[]): string | null
  /** z-order: later is drawn on top, so a backdrop goes to the back */
  toFront(ids: string[]): void
  toBack(ids: string[]): void
  resizeSpaced(ids: string[], marked: string[], axis: SpacingAxis, delta: number): void
  tidy(ids: string[], gap?: number): void
  spacing(ids: string[], options: SpacingOptions): void
  select(ids: string[]): void
  selection(): string[]
  zoomToFit(): void
  /** select these and zoom the view to them */
  zoomTo(ids: string[]): void
  bounds(): Box | null
  components(query?: string): ComponentSummary[]
  describe(kind: string): ComponentInfo | null
  /**
   * Standalone SVG of these nodes (default: the whole drawing), no fonts
   * inlined. Synchronous, so it draws with the icon catalogs the canvas has
   * already pulled in — which is every icon on screen.
   */
  svg(ids?: string[]): string
}

declare global {
  interface Window {
    squig?: SquigAgentApi
  }
}

/** The store's document, borrowed — safe to hand to lib/doc, which never mutates. */
function current(): SquigDocument {
  const s = useSquig.getState()
  return { fileName: s.fileName, look: lookOf(s), nodes: s.nodes, order: s.order, variations: s.variations, comments: s.comments }
}

const api: SquigAgentApi = {
  version: 1,
  documentId: () => useSquig.getState().docId,
  resizeSpaced(ids, marked, axis, delta) {
    const s = useSquig.getState()
    s.edit(() => s.updateNodes(resizeSpacedNodes(ids.map((id) => s.nodes[id]).filter(Boolean), marked, axis, delta)))
  },
  tidy(ids, gap) {
    const s = useSquig.getState()
    s.edit(() => s.updateNodes(tidyNodes(ids.map((id) => s.nodes[id]).filter(Boolean), gap)))
  },
  spacing(ids, options) {
    const s = useSquig.getState()
    s.edit(() => s.updateNodes(spaceNodes(ids.map((id) => s.nodes[id]).filter(Boolean), options)))
  },

  doc: () => structuredClone(current()),
  serialize: () => useSquig.getState().serialize(),
  load: (json) => useSquig.getState().loadDoc(json),

  add(nodes) {
    // lib/doc does the arguing; what comes back out of it has settled arrow
    // anchors on it, so the store gets the vouched copy rather than the input
    // cloned on the way in: the store keeps what it is handed, in history
    // too, and a caller that goes on editing its own object must not be
    // editing an undo step
    const before = current()
    const after = addNodes(before, structuredClone(nodes))
    const ids = after.order.slice(before.order.length)
    const store = useSquig.getState()
    store.addNodes(ids.map((id) => after.nodes[id]))
    // the store selects everything it was handed, and a locked layer must
    // never be in the selection or Delete takes the backdrop with it
    const loose = ids.filter((id) => !after.nodes[id].locked)
    if (loose.length !== ids.length) store.setSelection(loose)
    return ids
  },
  addComponent: (kind, at) => api.add([componentNode(kind, at)])[0],
  addText: (text, at) => api.add([textNode(text, at)])[0],
  addShape: (shape, at) => api.add([shapeNode(shape, at)])[0],
  addArrow: (opts) => api.add([arrowNode(opts, useSquig.getState().nodes)])[0],

  update(id, patch) {
    const before = current()
    const after = updateNode(before, id, structuredClone(patch))
    // the change can reach past the node named — a group left with one
    // member dissolves on its partner too — so commit every node that moved
    const changed: Record<string, SquigNode> = {}
    for (const [nid, n] of Object.entries(after.nodes)) if (n !== before.nodes[nid]) changed[nid] = n
    const store = useSquig.getState()
    // updateNodes on its own is the store's mid-drag write and takes no
    // checkpoint; an agent's change is a finished edit, so it gets one
    store.edit(() => {
      store.updateNodes(changed)
      // a locked node leaves the selection, and a group that just dissolved
      // stops being what the selection stands for
      const s = useSquig.getState()
      const loose = s.selection.filter((i) => !after.nodes[i]?.locked)
      const gid = s.selectionGroupId
      const groupAlive = !!gid && loose.some((i) => after.nodes[i]?.groupIds?.includes(gid))
      if (loose.length !== s.selection.length || (gid && !groupAlive)) s.setSelection(loose, groupAlive ? gid : null)
    })
  },
  remove: (ids) => useSquig.getState().removeNodes(ids),

  group(ids) {
    useSquig.getState().setSelection(ids)
    useSquig.getState().groupSelected()
    return useSquig.getState().selectionGroupId
  },

  toFront: (ids) => useSquig.getState().bringToFront(ids),
  toBack: (ids) => useSquig.getState().sendToBack(ids),

  select: (ids) => useSquig.getState().setSelection(ids),
  selection: () => [...useSquig.getState().selection],

  zoomToFit: () => useSquig.getState().zoomToFit(),
  zoomTo(ids) {
    useSquig.getState().setSelection(ids)
    useSquig.getState().zoomToSelection()
  },
  bounds: () => docBounds(current()),

  components: (query) => listComponents(query),
  describe: (kind) => describeComponent(kind),

  svg(ids) {
    const d = current()
    const picked = ids ? new Set(ids) : null
    const list = picked ? d.order.filter((id) => picked.has(id)).map((id) => d.nodes[id]) : nodesOf(d)
    return renderSvg(list, d.look)
  },
}

export function installAgentBridge(): void {
  if (typeof window === "undefined" || window.squig === api) return
  window.squig = api
}

"use client"

import { z } from "zod"
import type { SquigAgentApi } from "./agent-bridge"
import { id, nodeFields, nodeInput } from "./agent/schema"
import { vouchNode } from "./doc"
import { useSquig } from "./store"
import { useCanvasSyncIssue } from "./agent/sync-status"

// Keep the draft's types local until lib.dom ships them. Older Chromium builds
// used navigator.modelContext and explicit unregistration instead of a signal.
export interface WebMCPTool {
  name: string
  description: string
  inputSchema: object
  annotations: { readOnlyHint: boolean; untrustedContentHint: boolean }
  execute(input: unknown, options?: { signal?: AbortSignal }): Promise<unknown>
}
export interface ModelContext {
  registerTool(
    tool: WebMCPTool,
    options?: { signal: AbortSignal }
  ): void | Promise<void>
  unregisterTool?(name: string): void
}

const ids = z
  .array(id)
  .max(1000)
  .refine((v) => new Set(v).size === v.length, "Use each node ID once")
  .describe("Node IDs from squig_read_canvas")
const finite = z.number().finite().min(-100000).max(100000)
const axis = z.enum(["x", "y"])
const gap = finite.nonnegative()
const props = z.record(z.string(), z.unknown())
const at = nodeFields
  .pick({
    x: true,
    y: true,
    w: true,
    h: true,
    seed: true,
    rotation: true,
    locked: true,
  })
  .extend({ id: id.optional() })
  .strict()
const target = {
  documentId: z
    .string()
    .min(1)
    .describe(
      "Current documentId returned by squig_read_canvas; protects against editing a different file"
    ),
}
const textAt = at
  .extend(
    nodeFields.pick({
      fontSize: true,
      align: true,
      bold: true,
      italic: true,
      underline: true,
      ink: true,
      boxed: true,
      boxFill: true,
      link: true,
    }).shape
  )
  .omit({ h: true })
const shapeAt = at
  .extend(
    nodeFields.pick({ fill: true, stroke: true, ink: true, dashed: true }).shape
  )
  .extend({ w: finite.nonnegative(), h: finite.nonnegative() })
const arrowEnd = z.union([id, z.tuple([finite, finite])])

export function createWebMCPTools(api: SquigAgentApi): WebMCPTool[] {
  function existing(picked: string[], editable = false) {
    const { nodes } = useSquig.getState()
    for (const key of picked) {
      if (!Object.hasOwn(nodes, key))
        throw new Error(`Unknown node: ${key}. Read the canvas again.`)
      if (editable && nodes[key].locked)
        throw new Error(`Node ${key} is locked. Unlock it in the canvas first.`)
    }
  }
  function tool<T extends z.ZodType>(
    name: string,
    description: string,
    schema: T,
    run: (input: z.output<T>) => unknown,
    readOnly = false,
    untrusted = false
  ): WebMCPTool {
    return {
      name: `squig_${name}`,
      description,
      inputSchema: z.toJSONSchema(schema, { target: "draft-07" }),
      annotations: { readOnlyHint: readOnly, untrustedContentHint: untrusted },
      async execute(input, options) {
        try {
          options?.signal?.throwIfAborted()
          const value = schema.parse(input)
          const state = useSquig.getState()
          if (!state.hydrated)
            throw new Error(
              "The canvas is still opening. Try again once it is ready."
            )
          const search = typeof location === "undefined" ? null : new URLSearchParams(location.search)
          if (search?.has("agent")) throw new Error("The old canvas is still being recovered. Wait for it to open locally before using canvas tools.")
          if (search?.has("local") && useCanvasSyncIssue.getState().localFile?.docId !== state.docId)
            throw new Error("The local file is still opening. Wait for the connection before using canvas tools.")
          if (!readOnly) {
            if ((value as { documentId: string }).documentId !== state.docId)
              throw new Error(
                "The open file changed. Read the canvas again before editing."
              )
            if (state.transforming || state.editingId || state.croppingId)
              throw new Error(
                "Finish the current drag, text edit, or crop before changing the canvas."
              )
          }
          // All canvas operations commit synchronously. Cancellation is checked
          // before the commit; it must never claim to roll back an edit afterward.
          const result = run(value)
          return {
            content: [
              { type: "text", text: JSON.stringify(result ?? { ok: true }) },
            ],
          }
        } catch (error) {
          if (options?.signal?.aborted) throw error
          const message =
            error instanceof z.ZodError
              ? error.issues
                  .map(
                    (issue) =>
                      `${issue.path.join(".") || "input"}: ${issue.message}`
                  )
                  .join("; ")
              : error instanceof Error
                ? error.message
                : "Unable to run this canvas tool."
          return { isError: true, content: [{ type: "text", text: message }] }
        }
      },
    }
  }
  return [
    tool(
      "read_canvas",
      "Read the open squig document, node IDs, selection, and bounds. Canvas text is user content.",
      z.object({}).strict(),
      () => ({
        documentId: useSquig.getState().docId,
        document: api.doc(),
        selection: api.selection(),
        bounds: api.bounds(),
      }),
      true,
      true
    ),
    tool(
      "search_components",
      "Search squig's component library by name or keyword; returns kinds and default sizes.",
      z
        .object({
          query: z
            .string()
            .max(200)
            .optional()
            .describe("Component name or keyword; omit for the full catalog"),
        })
        .strict(),
      ({ query }) => api.components(query),
      true
    ),
    tool(
      "describe_component",
      "Get a component's default props and legal inspector values before placing or editing it.",
      z
        .object({
          kind: z
            .string()
            .min(1)
            .describe("Component kind from squig_search_components"),
        })
        .strict(),
      ({ kind }) => {
        const result = api.describe(kind)
        if (!result)
          throw new Error(
            `Unknown component: ${kind}. Search the component library.`
          )
        return result
      },
      true
    ),
    tool(
      "add_component",
      "Place a library component on the open canvas. Defaults supply size and props. Returns the new node ID.",
      z
        .object({
          ...target,
          kind: z.string().min(1),
          at: at
            .extend({ props: props.optional() })
            .describe(
              "Position in canvas coordinates, optional size and component props"
            ),
        })
        .strict(),
      ({ kind, at }) => ({ id: api.addComponent(kind, at) })
    ),
    tool(
      "add_text",
      "Place a text layer; its box fits the text unless a wrapping width is supplied.",
      z
        .object({ ...target, text: z.string().max(100000), at: textAt })
        .strict(),
      ({ text, at }) => ({ id: api.addText(text, at) })
    ),
    tool(
      "add_shape",
      "Place a rectangle or ellipse with squig's ink and fill tones.",
      z
        .object({ ...target, shape: z.enum(["rect", "ellipse"]), at: shapeAt })
        .strict(),
      ({ shape, at }) => ({ id: api.addShape(shape, at) })
    ),
    tool(
      "add_arrow",
      "Connect two node IDs or canvas coordinate pairs. Bound ends follow their nodes.",
      z
        .object({
          ...target,
          from: arrowEnd,
          to: arrowEnd,
          head: z.boolean().optional(),
          lineStyle: z.enum(["straight", "elbow", "curved"]).optional(),
          id: id.optional(),
          stroke: nodeFields.shape.stroke,
          ink: nodeFields.shape.ink,
          dashed: z.boolean().optional(),
        })
        .strict(),
      (opts) => {
        existing(
          [opts.from, opts.to].filter(
            (end): end is string => typeof end === "string"
          )
        )
        return { id: api.addArrow(opts) }
      }
    ),
    tool(
      "add_nodes",
      "Add a batch of complete .squig.json nodes in one undo step. All nodes are validated before insertion. Use the individual creation tools for default sizes and generated IDs.",
      z
        .object({
          ...target,
          nodes: z
            .array(
              nodeInput.extend({
                id,
                seed: z.number().int().nonnegative(),
                w: finite.nonnegative(),
                h: finite.nonnegative(),
              })
            )
            .min(1)
            .max(1000),
        })
        .strict(),
      ({ nodes }) => ({ ids: api.add(nodes.map(vouchNode)) })
    ),
    tool(
      "update_node",
      "Update an unlocked node's fields or component props. Keeps its ID; one undo step.",
      z
        .object({
          ...target,
          id,
          patch: nodeInput
            .omit({ id: true, type: true })
            .partial()
            .strict()
            .describe(
              "Fields to change; props merge with existing component props"
            ),
        })
        .strict(),
      ({ id, patch }) => {
        existing([id], true)
        api.update(id, patch)
      }
    ),
    tool(
      "remove_nodes",
      "Delete unlocked nodes from the open canvas. The user can undo this edit.",
      z
        .object({
          ...target,
          ids: ids.refine((v) => v.length > 0, "Supply at least one node"),
        })
        .strict(),
      ({ ids }) => {
        existing(ids, true)
        api.remove(ids)
      }
    ),
    tool(
      "arrange_nodes",
      "Group, change stacking order, tidy, set spacing, or resize marked nodes while keeping gaps. One undo step.",
      z
        .object({
          ...target,
          ids: ids.refine((v) => v.length > 0, "Supply at least one node"),
          arrangement: z.discriminatedUnion("action", [
            z.object({ action: z.literal("group") }).strict(),
            z.object({ action: z.enum(["front", "back"]) }).strict(),
            z
              .object({ action: z.literal("tidy"), gap: gap.optional() })
              .strict(),
            z
              .object({
                action: z.literal("spacing"),
                axis,
                gap,
                order: ids.optional(),
              })
              .strict(),
            z
              .object({
                action: z.literal("resize_spaced"),
                marked: ids,
                axis,
                delta: finite,
              })
              .strict(),
          ]),
        })
        .strict(),
      ({ ids, arrangement: a }) => {
        existing(ids, true)
        if (a.action !== "front" && a.action !== "back" && ids.length < 2)
          throw new Error("This arrangement needs at least two nodes")
        if (a.action === "group") return { groupId: api.group(ids) }
        if (a.action === "front") return api.toFront(ids)
        if (a.action === "back") return api.toBack(ids)
        if (a.action === "tidy") return api.tidy(ids, a.gap)
        if (a.action === "spacing") {
          if (
            a.order &&
            (a.order.length !== ids.length ||
              a.order.some((key) => !ids.includes(key)))
          )
            throw new Error(
              "order must contain each selected node ID exactly once"
            )
          return api.spacing(ids, a)
        }
        if (a.action === "resize_spaced") {
          if (!a.marked.length || a.marked.some((key) => !ids.includes(key)))
            throw new Error("marked must name nodes from ids")
          return api.resizeSpaced(ids, a.marked, a.axis, a.delta)
        }
      }
    ),
    tool(
      "set_view",
      "Select unlocked nodes, zoom to nodes, or fit the whole canvas. Changes the visible UI, without editing the document.",
      z
        .object({
          ...target,
          action: z.enum(["select", "zoom_to", "zoom_to_fit"]),
          ids: ids.optional(),
        })
        .strict(),
      ({ action, ids }) => {
        if (action === "zoom_to_fit") {
          api.zoomToFit()
          return
        }
        if (!ids || (action === "zoom_to" && !ids.length))
          throw new Error(
            "Supply node IDs; select accepts an empty array to clear selection."
          )
        existing(ids, true)
        if (action === "select") api.select(ids)
        else api.zoomTo(ids)
      }
    ),
    tool(
      "export_canvas",
      "Return the open drawing as .squig.json or standalone SVG. SVG can include only the supplied node IDs. Returns user content; does not download or upload a file.",
      z
        .object({ format: z.enum(["json", "svg"]), ids: ids.optional() })
        .strict(),
      ({ format, ids }) => {
        if (format === "json" && ids)
          throw new Error("Node filtering is supported for SVG only.")
        if (ids) existing(ids)
        return {
          format,
          data: format === "json" ? api.serialize() : api.svg(ids),
        }
      },
      true,
      true
    ),
    tool(
      "import_document",
      "Open a .squig.json as a new local file. Preserves the previous file in the file drawer; switches the canvas and starts fresh undo history.",
      z
        .object({
          ...target,
          json: z
            .string()
            .max(16000000)
            .describe("Complete .squig.json document"),
        })
        .strict(),
      ({ json }) => {
        if (!api.load(json))
          throw new Error(
            "Invalid .squig.json. Supply a document with nodes and order."
          )
        return { documentId: useSquig.getState().docId }
      }
    ),
  ]
}

export function findModelContext(
  doc: object,
  nav: object
): ModelContext | undefined {
  const current = (doc as { modelContext?: ModelContext }).modelContext
  if (typeof current?.registerTool === "function") return current
  const legacy = (nav as { modelContext?: ModelContext }).modelContext
  if (typeof legacy?.registerTool === "function") return legacy
}

const pendingRegistrations = new WeakMap<ModelContext, Promise<void>>()

/** Own only our registrations; never clear another integration's context. */
export function registerWebMCP(
  context: ModelContext,
  tools: WebMCPTool[],
  reportError: (error: unknown) => void = (error) =>
    console.warn("Squig WebMCP registration failed", error)
): () => void {
  const controller = new AbortController()
  const registered: string[] = []
  const remove = (name: string) => {
    try {
      context.unregisterTool?.(name)
    } catch (error) {
      reportError(error)
    }
  }
  const stop = () => {
    controller.abort()
    for (const name of registered.splice(0)) remove(name)
  }
  // Starting in a microtask lets React's setup/cleanup/setup cycle cancel the
  // first mount before it registers anything, including on legacy browsers.
  const pending = (async () => {
    // A pending legacy registration must finish and clean up before a new
    // mount reuses its name; otherwise its late cleanup can remove the new tool.
    await pendingRegistrations.get(context)
    try {
      for (const tool of tools) {
        if (controller.signal.aborted) return
        await context.registerTool(
          {
            ...tool,
            execute: (input, options) => {
              controller.signal.throwIfAborted()
              return tool.execute(input, options)
            },
          },
          { signal: controller.signal }
        )
        if (controller.signal.aborted) {
          remove(tool.name)
          return
        }
        registered.push(tool.name)
      }
    } catch (error) {
      const cancelled = controller.signal.aborted
      stop()
      if (!cancelled) reportError(error)
    }
  })()
  pendingRegistrations.set(context, pending)
  return stop
}

export function installWebMCP(api: SquigAgentApi): () => void {
  if (typeof window === "undefined" || !window.isSecureContext) return () => {}
  try {
    const context = findModelContext(document, navigator)
    return context ? registerWebMCP(context, createWebMCPTools(api)) : () => {}
  } catch (error) {
    console.warn("Squig WebMCP is unavailable", error)
    return () => {}
  }
}

